pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor (other), caller (beneficiary), depositorAmount, callerAmount
    // We keep wide bounds but ensure amounts fit into uint and are >0 where needed.
    function testFuzz_property(address depositor, address caller, uint256 depositorAmount, uint256 callerAmount) public {
        // keep addresses non-zero and distinct to allow the scenario where someone else deposited
        vm.assume(depositor != address(0));
        vm.assume(caller != address(0));
        vm.assume(depositor != caller);

        // bound amounts to reasonable range to avoid overflow in test harness
        depositorAmount = bound(depositorAmount, 1, 1 ether);
        callerAmount = bound(callerAmount, 1, 1 ether);

        // Set balances so they can deposit
        vm.deal(depositor, depositorAmount);
        vm.deal(caller, callerAmount);

        // depositor deposits first (another party)
        vm.prank(depositor);
        c.deposit{value: depositorAmount}();

        // caller deposits his credit
        vm.prank(caller);
        c.deposit{value: callerAmount}();

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // caller calls withdrawAll; capture whether it reverts via try/catch
        bool ok;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful withdraw on the reference contract, the contract should not lose more than caller's recorded credit.
        // We observe only via address(c).balance. This is the single assertion required.
        // If the call reverted, we still assert the same relation (no unexpected extra loss); a revert implies no state change so relation holds.
        uint256 after = address(c).balance;

        // The invariant: after >= before - callerAmount
        // i.e., the contract's balance decreased by at most callerAmount
        assertTrue(after + callerAmount >= before);
    }
}

